INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ju-chunqiu','莒','["莒","莒国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1046,"month":1,"confidence":"year"},"end":{"year":-454,"month":12,"confidence":"approximate_year"}},{"rank":"子","start":{"year":-453,"month":1,"confidence":"approximate_year"},"end":{"year":-431,"month":12,"confidence":"month"}}]}','cn','east_asia',-1046,1,NULL,'year',-431,12,NULL,'month',-12540,-5149,'ochre',NULL,NULL,'周初（断代工程取前1046年）封兹舆期；至春秋早期世系与具体在位年长期失载，以史料缺占位至前616年，后接可考莒君；前481年后至前431年楚灭莒前再以史料缺占位。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-state-chunqiu','杞','["杞","杞国"]',NULL,'{"periods":[{"rank":"伯","start":{"year":-750,"month":1,"confidence":"year"},"end":{"year":-445,"month":12,"confidence":"month"}}]}','cn','east_asia',-750,1,NULL,'year',-445,12,NULL,'month',-8988,-5317,'ochre',NULL,NULL,'杞为夏后氏后裔受封的诸侯国，早期世系与建国年代记载不足。春秋时期在今山东一带活动，前445年楚惠王灭杞。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('teng-chunqiu','滕','["滕","滕国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1045,"month":1,"confidence":"year"},"end":{"year":-711,"month":12,"confidence":"year"}},{"rank":"子","start":{"year":-710,"month":1,"confidence":"year"},"end":{"year":-296,"month":12,"confidence":"approximate_year"}}]}','cn','east_asia',-1045,1,NULL,'year',-296,12,NULL,'approximate_year',-12528,-3529,'ochre',NULL,NULL,'姬姓诸侯国，周武王封错叔绣。前414年一度为越所灭，后复国，前296年为宋所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xue-chunqiu','薛','["薛","薛国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-548,"month":1,"confidence":"year"},"end":{"year":-454,"month":12,"confidence":"approximate_year"}},{"rank":"伯","start":{"year":-453,"month":1,"confidence":"approximate_year"},"end":{"year":-327,"month":12,"confidence":"month"}}]}','cn','east_asia',-548,1,NULL,'interpolated_by_other',-327,12,NULL,'month',-6564,-3901,'ochre',NULL,NULL,'任姓诸侯国。薛献公在位始年不详，前511年卒；薛襄公、薛公比、薛惠公的在位见于《春秋》《左传》。');
