INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r3','密州','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒犂比公（密州），前576–前542年在位。据《左传》称其「虐」、好争战，为莒国最活跃时期；死后莒渐衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒犂比公"}]','犂比公',NULL,'莒犂比公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r4','舆','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒子舆（展舆），犂比公子，前541年在位仅一年。犂比公暴虐时先被立为太子，终短暂即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒子舆"}]',NULL,NULL,'子舆','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r5','去疾','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒著丘公（去疾），犂比公子，前540–前528年在位。著丘公卒后，子郊公狂与弟庚舆争立，引发内乱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒著丘公"}]','著丘公',NULL,'莒著丘公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r6','庚舆','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒共公（庚舆），犂比公子，好铸剑以人试刃，暴虐失国，前527–前519年在位。国人逐之，迎郊公狂复位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒共公"}]','共公',NULL,'莒共公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ju-r7','狂','ju-chunqiu','[]','己',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','莒郊公（狂），著丘公子，两度在位（前528年数月、前518–前481年）。柱厉叔知其不遇而去海上，后返国殉之；前481年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/莒郊公"}]','郊公',NULL,'莒郊公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-ai','阏路','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞哀公名阏路，承杞湣公之后、由出公继位。其统治处于杞国亡于楚之前，传世材料未保存更多可核的个人事迹。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞哀公"},{"label":"《史记·陈杞世家》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','哀公',NULL,'杞哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-chu','欶','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞出公名欶，在战国初期统治杞国，后由简公继位。前445年楚灭杞；出公个人政事在传世文献中记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞出公"},{"label":"《史记·陈杞世家》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷036"},{"label":"《史记》楚世家：楚惠王四十四年灭杞","url":"https://zh.wikisource.org/wiki/史記/卷040"}]','出公',NULL,'杞出公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-dao','成','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞悼公名成，在位时处于鲁昭公、定公之际，后由隐公继位。关于其个人政事，现存史料远少于其在位年次记录。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞悼公"},{"label":"《史记·陈杞世家》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','悼公',NULL,'杞悼公','[]');
