INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r1','','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夏后姒姓后裔，谥武公。传统世系列其为杞国君主，并非杞国始封者；《史记·陈杞世家》记其在位四十七年，通行年表系于前750年至前704年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞武公"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','武公',NULL,'杞武公','[]');
