INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r1c','','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞成公，前654–前637年在位。在位时将国都迁至缘陵（今山东昌乐东南）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞成公"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','成公',NULL,'杞成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-r2','姑容','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞桓公（姑容），前636–前567年在位，在位七十年，为杞国在位最久之君。屡遭强邻压迫迁国，《列子·天瑞》「杞人忧天」故事或与此忧患有关。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞桓公"}]','桓公',NULL,'杞桓公','[]');
