INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-state-xiao','匄','qi-state-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杞孝公名匄，为杞桓公之子。其在位处于春秋中期，继位后由弟弟文公承统；现存记载未载显著对外战争或制度变革。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杞孝公"},{"label":"《史记·陈杞世家》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','孝公',NULL,'杞孝公','[]');
