INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-gong-middle','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周中期滕侯簋所追祭的前任滕公，与早期滕侯方鼎、簋所见滕公应作区别。本名、具体世次及在位年失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hou-middle','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周中期滕侯簋的作器者，为前任滕公作尊彝。本名、具体世次及在位年失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hou-su','苏','teng-chunqiu','["滕侯𩵦","姬𩵦","滕侯苏"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','两周之际滕侯盨的作器者，为其父滕仲作器。张志鹏释名苏，另一释法作𩵦；具体世次和在位年代失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-hu','虎','teng-chunqiu','["孟虎","滕侯虎","姬敢"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕虎簋的作器者，铭文称其父为公命仲。通常与《礼记·檀弓上》的孟虎相联系，是滕伯文的叔父；部分世系表将其列为第五世滕君，张志鹏则将该世君主推为伯文之父。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《礼记·檀弓上》：滕伯文与孟虎的亲属关系","url":"https://ctext.org/text.pl?if=gb&node=9665&show=parallel"}]',NULL,NULL,'虎','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r0','绣','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','错叔绣是周武王所封的滕国始封君，姬姓。现存文献将他列为周初诸侯，关于其封地经营与具体在位时间没有明确记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕错叔"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"}]',NULL,NULL,'错叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r1','穀','teng-chunqiu','["滕庄公","滕侯穀","姬毂"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《春秋》隐公七年记滕侯卒，年当-716年；即位年失考。杨甲《六经图》称庄公、名穀，陈厚耀《春秋世族谱》名毂；世次数亦有不同说法。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕庄公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]','庄公',NULL,'庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r10','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《左传·僖公二十二年》记滕君参与前638年的诸侯交往，但没有记下他的本名；现存史料也未能确认其具体在位起讫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕子"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"}]',NULL,NULL,'滕子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r11','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《左传·庄公十六年》记载前678年滕君与齐、宋等国发生外交往来，但未载其本名；个人生平目前无从补充。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕子"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"}]',NULL,NULL,'滕子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r12','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《左传·桓公二年》（前710年）记载其朝鲁；本名及卒年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕子"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r13','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','鲁隐公十一年（-712年）与薛侯朝鲁的滕侯。张志鹏考定其在位为-715至-711年；本名失考，后继滕子于-710年朝鲁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r16','麇','teng-chunqiu','["滕考公","滕定公","姬麋","姬糜"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','战国时期滕君、滕文公之父。赵岐《孟子章句》将定公对应《世本》的考公麇，名字亦作麋、糜。梁涛《孟子行年考》将其卒年考定为-324年；世子遣然友向孟子问丧礼，即位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕考公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《孟子注疏》卷五：赵岐注考公／定公、元公／文公","url":"https://ctext.org/wiki.pl?chapter=372734&if=en"}]','定公,考公',NULL,'定公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r17','弘','teng-chunqiu','["滕文公（战国）","滕元公","姬宏"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕定公之子，战国时期滕文公。赵岐《孟子章句》对应《世本》的元公弘。为世子时赴楚，途经宋见孟子；父卒后遣然友问丧礼，后向孟子问治国之道。依梁涛、张志鹏考证，约-323至-316年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕元公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《孟子注疏》卷五：赵岐注考公／定公、元公／文公","url":"https://ctext.org/wiki.pl?chapter=372734&if=en"},{"label":"滕文公年表（前323—前316年，与本包所采考证框架对照）","url":"https://zh.wikipedia.org/wiki/滕文公"}]','文公,元公',NULL,'文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r18','昃','teng-chunqiu','["滕侯昃"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕侯昃戈、敦铭文所见滕君。器物形制被考定为战国中期，具体在位年及世次不详；另有将其对应春秋滕隐公的说法。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯昃"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r19','丘','teng-chunqiu','["滕公丘"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','部分后世世系表所列的滕末君丘，所据为《通志·氏族略》滕氏条“至公邱”等文字。该条世数与灭国记载存在矛盾，其作为末君的身份及在位年代尚不能确证。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕公丘"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《通志》卷二十六·氏族略：滕氏（末君异说所据原文）","url":"https://zh.wikisource.org/wiki/通志_(四庫全書本)/卷026"}]',NULL,NULL,'公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r2','寿','teng-chunqiu','["滕文公（春秋）","姬绣"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕昭公之子，春秋时期滕文公，-599至-575年在位。《春秋》成公十六年记其卒；旧谱名寿，《春秋释例》另名绣。继任者为滕成公原。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕文公_(春秋)"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]','文公',NULL,'滕文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r20','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','错叔绣之后的早期滕君，处于西周成康之际。金文称滕伯、滕公，为康王时期滕侯的前任；本名与具体在位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r21','','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周康王时期的滕君，《滕侯方鼎》与《滕侯簋》铭文称滕侯；《滕侯簋》为前任滕公作器。本名与具体在位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'滕侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r22','命仲','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《滕虎簋》铭文所载滕虎之父命仲。张志鹏据金文与亲属关系推为康昭之际的第四世滕君；具体在位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/命仲"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'命仲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r23','？','teng-chunqiu','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','命仲之子、滕伯文之父，本名失载。张志鹏据世系推为昭王时期的第五世滕君；与滕虎的关系及该世君主身份有不同考证。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'','[]');
