INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r6','虞毋','teng-chunqiu','["姬虞母"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕隐公（虞毋），顷公之子，前490–前484年在位。为春秋可考末代滕君之一，其后世系失考至越灭滕复国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕隐公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]','隐公',NULL,'滕隐公','[]');
