INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r8','郑','teng-chunqiu','["姬辙"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕国君主郑位于宣公与昭公之间，个人在位年代失考；现存世系和诸侯记载不足以确认其更详细的事迹。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕孝侯"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"}]','孝侯',NULL,'孝侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-r9','元','teng-chunqiu','["姬毛伯"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕君元在前615年朝鲁、前600年去世，相关记录见于《春秋》及诸侯年表；其名另有毛伯等异说，不能确定“元”为本名。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕昭公"},{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"}]','昭公',NULL,'昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('teng-zhong','仲','teng-chunqiu','["滕仲"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','滕侯𩵦盨铭文所载作器者之父滕仲，时代约属西周晚期。是否曾为滕君存在争议，具体世次与年代失考。','[{"label":"维基百科：滕国国君表（异说对照）","url":"https://zh.wikipedia.org/wiki/滕国"},{"label":"张志鹏《滕国新考》（2011）：金文、世系与存灭考证","url":"https://www.fdgwz.org.cn/Web/Show/1428"}]',NULL,NULL,'仲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-shi','田巿','jiaodong-warring','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','秦末齐国宗室，田儋之子。前208年，田儋在临济战死后，齐人先立齐王建之弟田假为王；田儋从弟田荣驱逐田假，继而立田巿为齐王。项羽分封诸侯时，改封田巿为胶东王。前206年，田荣攻杀田巿于即墨。','[{"label":"《史记·田儋列传》","url":"https://zh.wikisource.org/wiki/史记/卷094"}]',NULL,NULL,'胶东王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r1','谷','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','春秋薛国国君，任姓，名谷，谥献公。在位始年不详。《左传·昭公三十一年》载夏四月丁巳薛伯谷卒，秋葬薛献公（前511年）。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛献公"},{"label":"《左传·昭公三十一年》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/昭公#昭公三十一年"},{"label":"《春秋滕薛杞越莒邾許七國統表》卷三（引《左传》杜注、孔疏）","url":"https://www.shidianguji.com/zh/book/CADAL02030731/chapter/1l6u63jtnvzfq"}]','献公',NULL,'薛献公','[]');
