INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r3','比','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','公比，薛国君主。在薛（前497年—前497年）在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛公比"}]',NULL,NULL,'公比','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xue-r4','夷','xue-chunqiu','[]','任',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','是春秋时代薛国国君，任姓，伯爵，名夷。鲁定公十三年（前497年），薛国人弑杀薛公比，拥立公子夷为君。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/薛惠公"}]','惠公',NULL,'薛惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-jia-dai','赵嘉','dai-warring','[]','嬴','赵',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赵悼襄王之子、赵王迁之兄。前228年秦军攻陷邯郸、俘赵王迁后，赵嘉率宗族及残部退往代地，自立为代王，延续赵氏统治，并与燕联合抗秦。前222年秦军攻代，赵嘉被俘，代政权覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/代王嘉"}]',NULL,NULL,'代王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-chao','朝','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周威公太子；前367年威公卒后与弟根分国，朝据王城为西周惠公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','惠公',NULL,'西周惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-gen','班','zhou-guo-east','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周威公少子，《韩非子》作根，《纪年》作杰；赵韩扶持下据巩为东周惠公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东周国"}]','惠公',NULL,'东周惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-jie','揭','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','揭为周考王之弟，受封于王城并承袭周公职事，成为西周国的开端。此处“西周国”指战国时期王畿内的诸侯政权，不是周朝西周时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"},{"label":"《左传》（中国哲学书电子化计划）","url":"https://ctext.org/chun-qiu-zuo-zhuan"},{"label":"张志鹏《滕国新考》（2011）","url":"https://www.fdgwz.org.cn/Web/Show/1428"},{"label":"《史记·陈杞世家》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','桓公',NULL,'西周桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-jiu','咎','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周末任君，前256年秦攻西周国，纳土降秦后卒。中间武公世系在位年失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','文公',NULL,'西周文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-wugong','','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西周惠公长子，承惠公为西周国君，文公之父。《史记·周本纪》及《史记集解》引徐广注可证其世系，但未载本名；部分后世君主表称其名共，出处未详。在位起讫年无可靠记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周武公"},{"label":"《史记·周本纪》","url":"https://ctext.org/shiji/zhou-ben-ji"}]','武公',NULL,'武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-guo-zao','灶','zhou-guo-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中国历史上的古国名，在今日河南洛陽一帶，战国时期的一个小国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周国"}]','威公',NULL,'西周威公','[]');
